css:
.social-sim-container {
    padding: 28px;
    background: linear-gradient(135deg, #1a0a2e 0%, #16213e 40%, #0a2647 70%, #0d1f3c 100%);
    min-height: 100vh;
    font-family: -apple-system, 'Inter', 'Segoe UI', sans-serif;
    color: #ffffff;
}
.social-sim-header {
    background: rgba(255,255,255,0.06);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 20px;
    padding: 36px 32px 28px;
    text-align: center;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
}
.social-sim-header::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #E1306C, #833AB4, #405DE6, #00f2ea);
}
.social-sim-header-icon {
    font-size: 2.4rem;
    margin-bottom: 8px;
}
.social-sim-header h1 {
    font-size: 1.6rem;
    font-weight: 700;
    margin: 0 0 6px;
    background: linear-gradient(135deg, #E1306C, #833AB4, #405DE6);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}
.social-sim-subtitle {
    font-size: 0.85rem;
    color: rgba(255,255,255,0.55);
    margin: 0;
}
.social-sim-period-counter {
    text-align: center;
    font-size: 1rem;
    color: rgba(255,255,255,0.7);
    margin-bottom: 20px;
    letter-spacing: 0.05em;
}
.social-sim-period-counter span {
    margin: 0 3px;
}
.social-sim-briefing {
    background: rgba(255,255,255,0.06);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.1);
    border-left: 4px solid #833AB4;
    border-radius: 14px;
    padding: 20px 24px;
    margin-bottom: 24px;
}
.social-sim-briefing h4 {
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #c084fc;
    margin: 0 0 10px;
}
.social-sim-briefing p {
    font-size: 0.9rem;
    line-height: 1.6;
    color: rgba(255,255,255,0.85);
    margin: 0;
}
.social-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 24px;
}
.social-sim-kpi-card {
    background: rgba(255,255,255,0.07);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 16px;
    padding: 20px 16px;
    text-align: center;
    transition: background 0.25s ease, transform 0.2s ease;
}
.social-sim-kpi-card:hover {
    background: rgba(255,255,255,0.1);
    transform: translateY(-3px);
}
.social-sim-kpi-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: rgba(255,255,255,0.5);
    margin-bottom: 8px;
}
.social-sim-kpi-value {
    font-size: 1.6rem;
    font-weight: 700;
}
.social-sim-kpi-budget .social-sim-kpi-value {
    color: #60a5fa;
}
.social-sim-kpi-followers .social-sim-kpi-value {
    color: #a78bfa;
}
.social-sim-kpi-sentiment .social-sim-kpi-value {
    color: #34d399;
}
.social-sim-kpi-revenue .social-sim-kpi-value {
    color: #fbbf24;
}
.social-sim-platform-stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
    margin-bottom: 24px;
}
.social-sim-platform-card {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 12px;
    padding: 14px 12px;
    text-align: center;
    transition: border-color 0.2s ease;
}
.social-sim-platform-card:hover {
    border-color: rgba(255,255,255,0.2);
}
.social-sim-platform-icon {
    font-size: 1.4rem;
    margin-bottom: 4px;
}
.social-sim-platform-name {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: rgba(255,255,255,0.45);
    margin-bottom: 6px;
}
.social-sim-platform-val {
    font-size: 1.1rem;
    font-weight: 600;
}
.social-sim-ig .social-sim-platform-val { color: #E1306C; }
.social-sim-tk .social-sim-platform-val { color: #00f2ea; }
.social-sim-li .social-sim-platform-val { color: #0A66C2; }
.social-sim-controls {
    background: rgba(255,255,255,0.06);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 16px;
    padding: 28px 24px;
    margin-bottom: 24px;
}
.social-sim-controls h3 {
    font-size: 1rem;
    font-weight: 600;
    margin: 0 0 20px;
    color: rgba(255,255,255,0.9);
}
.social-sim-input-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-bottom: 20px;
}
.social-sim-input-group {
    display: flex;
    flex-direction: column;
}
.social-sim-input-group label {
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: rgba(255,255,255,0.55);
    margin-bottom: 6px;
}
.social-sim-input-group input[type="number"],
.social-sim-input-group select {
    background: rgba(255,255,255,0.08);
    border: 1px solid rgba(255,255,255,0.15);
    color: #ffffff;
    border-radius: 10px;
    padding: 10px 14px;
    font-size: 0.95rem;
    transition: border-color 0.2s ease, background 0.2s ease;
    width: 100%;
    -webkit-appearance: none;
}
.social-sim-input-group input:focus,
.social-sim-input-group select:focus {
    outline: none;
    border-color: #833AB4;
    background: rgba(131,58,180,0.12);
}
.social-sim-input-group select option {
    background: #16213e;
    color: #ffffff;
}
.social-sim-crisis-panel {
    background: rgba(239,68,68,0.1);
    border: 1px solid rgba(239,68,68,0.3);
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 20px;
}
.social-sim-crisis-panel h4 {
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #f87171;
    margin: 0 0 10px;
}
.social-sim-crisis-desc {
    font-size: 0.85rem;
    color: rgba(255,255,255,0.8);
    margin: 0 0 14px;
    line-height: 1.5;
}
.social-sim-crisis-panel select {
    background: rgba(255,255,255,0.08);
    border: 1px solid rgba(239,68,68,0.3);
    color: #ffffff;
    border-radius: 10px;
    padding: 10px 14px;
    font-size: 0.9rem;
    width: 100%;
    -webkit-appearance: none;
}
.social-sim-crisis-panel select option {
    background: #1a0a2e;
    color: #ffffff;
}
.social-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
}
.social-sim-submit-btn {
    background: linear-gradient(135deg, #833AB4, #405DE6);
    border: none;
    color: #ffffff;
    padding: 12px 32px;
    border-radius: 12px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: opacity 0.2s ease, transform 0.15s ease;
}
.social-sim-submit-btn:hover {
    opacity: 0.9;
    transform: translateY(-1px);
}
.social-sim-undo-btn {
    background: transparent;
    border: 1px solid rgba(255,255,255,0.2);
    color: rgba(255,255,255,0.6);
    padding: 10px 20px;
    border-radius: 10px;
    font-size: 0.85rem;
    cursor: pointer;
    transition: border-color 0.2s ease;
}
.social-sim-undo-btn:hover {
    border-color: rgba(255,255,255,0.4);
    color: rgba(255,255,255,0.8);
}
.social-sim-chart-section {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 16px;
    padding: 20px;
    margin-bottom: 24px;
    height: 320px;
}
.social-sim-history {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 16px;
    padding: 20px;
    overflow-x: auto;
}
.social-sim-container .table {
    color: rgba(255,255,255,0.85);
    margin: 0;
}
.social-sim-container .table thead th {
    border-color: rgba(255,255,255,0.12);
    color: rgba(255,255,255,0.5);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.social-sim-container .table td {
    border-color: rgba(255,255,255,0.06);
    font-size: 0.85rem;
    vertical-align: middle;
}
.social-sim-container .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(255,255,255,0.03);
}
@media (max-width: 768px) {
    .social-sim-container { padding: 16px; }
    .social-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .social-sim-platform-stats { grid-template-columns: 1fr; }
    .social-sim-input-grid { grid-template-columns: 1fr; }
    .social-sim-kpi-value { font-size: 1.3rem; }
    .social-sim-header h1 { font-size: 1.3rem; }
    .social-sim-chart-section { height: 260px; }
}
.social-sim-debrief {
    background: rgba(255,255,255,0.06);
    -webkit-backdrop-filter: blur(14px);
    backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.12);
    border-left: 4px solid #34d399;
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 24px;
}
.social-sim-debrief h3 {
    font-size: 1.1rem;
    font-weight: 700;
    margin: 0 0 14px;
    color: #ffffff;
}
.social-sim-debrief-tier {
    font-size: 1rem;
    color: #ffffff;
    margin-bottom: 14px;
}
.social-sim-debrief-tier strong { color: #34d399; }
.social-sim-debrief-metrics {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-bottom: 14px;
}
.social-sim-debrief-metrics span {
    font-size: 0.9rem;
    color: rgba(255,255,255,0.92);
    background: rgba(255,255,255,0.07);
    border: 1px solid rgba(255,255,255,0.14);
    border-radius: 10px;
    padding: 8px 14px;
}
.social-sim-debrief-insights {
    margin: 0;
    padding-left: 20px;
}
.social-sim-debrief-insights li {
    font-size: 0.9rem;
    color: rgba(255,255,255,0.9);
    line-height: 1.6;
    margin-bottom: 6px;
}
/* v1.2.0: accessibility and debrief (namespaced, append-only) */
.social-sim-container button:focus-visible,
.social-sim-container input:focus-visible,
.social-sim-container select:focus-visible { outline: 3px solid #fbbf24; outline-offset: 2px; }
.social-sim-container .social-sim-input-note { display: block; margin-top: 4px; font-size: 0.8rem; opacity: 0.85; }
.social-sim-container input[readonly] { opacity: 0.8; cursor: not-allowed; }
.social-sim-container select option { color: #111827; background: #ffffff; }
.social-sim-cm h4 { margin: 14px 0 6px; font-size: 1rem; }
.social-sim-cm ul { padding-left: 1.2rem; margin: 0; }
.social-sim-cm li { margin-bottom: 6px; line-height: 1.45; }
.social-sim-cm-score { font-size: 1.25rem; margin-bottom: 4px; }
.social-sim-cm-kpis, .social-sim-cm-sub { margin: 2px 0; }
@media (prefers-reduced-motion: reduce) {
  .social-sim-container *, .social-sim-container *::before, .social-sim-container *::after { animation: none !important; transition: none !important; }
}

