            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    instagramPct: 45,
                    tiktokPct: 40,
                    linkedinPct: 15,
                    contentFocus: 'mixed',
                    influencerType: 'mixed',
                    paidPct: 30,
                    crisisResponse: 'apologize'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var igInput = document.getElementById('instagramPctInput');
            var tkInput = document.getElementById('tiktokPctInput');
            var contentInput = document.getElementById('contentFocusSelect');
            var influencerInput = document.getElementById('influencerSelect');
            var paidInput = document.getElementById('paidPctInput');
            var crisisInput = document.getElementById('crisisResponseSelect');

            if (igInput) decisions.instagramPct = parseInt(igInput.value, 10) || 0;
            if (tkInput) decisions.tiktokPct = parseInt(tkInput.value, 10) || 0;
            /* v1.2.0: LinkedIn takes the remainder, so the three shares always total 100 */
            decisions.linkedinPct = 100 - (decisions.instagramPct || 0) - (decisions.tiktokPct || 0);
            if (contentInput) decisions.contentFocus = contentInput.value;
            if (influencerInput) decisions.influencerType = influencerInput.value;
            if (paidInput) decisions.paidPct = parseInt(paidInput.value, 10) || 0;
            if (crisisInput) decisions.crisisResponse = crisisInput.value;

            if (decisions.instagramPct < 0 || decisions.tiktokPct < 0 || decisions.linkedinPct < 0 ||
                decisions.instagramPct > 100 || decisions.tiktokPct > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('platform_warning'), 'warning'
                );
                return false;
            }

            if (decisions.paidPct < 0 || decisions.paidPct > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('paid_warning'), 'warning'
                );
                return false;
            }

            /* v1.1.0: removed validate-time DOM write (validation is side-effect free; refresh is event-driven). */
            return true;
        }

        calculateResults(state) {
            var r = this._computeRound(state);
            return {
                period: state.currentPeriod,
                igGrowth: r.igGrowth,
                tkGrowth: r.tkGrowth,
                liGrowth: r.liGrowth,
                totalFollowers: r.totalFollowers,
                engagementRate: r.engagementRate,
                revenue: r.revenue,
                igRevenue: r.igRevenue,
                tkRevenue: r.tkRevenue,
                liRevenue: r.liRevenue,
                sentiment: r.sentiment,
                sentimentChange: r.sentimentChange,
                organicReachPct: r.organicReachPct,
                budget: r.budget,
                overallScore: r.overallScore,
                score: r.overallScore
            };
        }

        /* v1.2.0 round model. Sources: case MKT-2026-620 and concept 620 (TikTok about 3x the impressions
           per peso of Instagram, conversion 0.3 vs 1.2 percent; Instagram organic reach falling; LinkedIn
           reaches gyms, universities and distributors; three soft-contract creators; crisis responses).
           Each platform has a saturating response, so a spread beats concentration; paid media has
           diminishing returns while unpaid reach decays every quarter; content and creators trade reach
           against conversion; crisis responses and risky content act through sentiment one quarter later. */
        _computeRound(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var t = Math.max(1, Math.min(this.ROUNDS.length, state.currentPeriod || 1));
            var B = 15;   /* COP millions per quarter */
            var ig = (d.instagramPct || 0) / 100, tk = (d.tiktokPct || 0) / 100, li = (d.linkedinPct || 0) / 100;
            var p = Math.max(0, Math.min(100, d.paidPct || 0)) / 100;

            var R = Math.pow(0.88, t - 1);
            var media = (1 - p) * R + 2.2 * p - 1.3 * p * p;

            var CT = {
                education:     { r: [1.0, 1.0, 1.1],    c: 1.10, s: 3,  e: 3.6 },
                entertainment: { r: [1.2, 1.45, 0.7],   c: 0.70, s: 1,  e: 5.5 },
                sales:         { r: [0.85, 0.85, 0.85], c: 1.30, s: -4, e: 2.0 },
                mixed:         { r: [1.05, 1.05, 1.05], c: 1.00, s: 1,  e: 3.4 }
            };
            var IN = {
                micro: { r: 0.95, c: 1.2, e: 1.4 },
                macro: { r: 1.35, c: 0.8, e: 0.7 },
                mixed: { r: 1.15, c: 1.0, e: 1.0 }
            };
            var C = CT[d.contentFocus] || CT.mixed;
            var I = IN[d.influencerType] || IN.mixed;

            if (d.influencerType === 'macro') ds.macroQuarters = (ds.macroQuarters || 0) + 1;
            else if (d.influencerType === 'mixed') ds.macroQuarters = (ds.macroQuarters || 0) + 0.5;
            /* from Q3 the big creators weigh competitor offers: reach built on them leaks away */
            var dep = (t >= 3) ? 1 - 0.15 * Math.min(2, ds.macroQuarters || 0) : 1;
            var lost = (typeof ds.reachLoss === 'number') ? ds.reachLoss : 1;
            ds.reachLoss = 1;
            var algo = [t === 3 ? 0.75 : 1, 1, 1];   /* Q3 Instagram algorithm change */

            var A = [16, 7, 20], SAT = [11, 7, 2], FPM = [700, 2600, 120];   /* sales per COP 1M at low spend, saturation, followers per COP 1M */
            var eff = [], sales = [];
            [ig, tk, li].forEach(function(sh, k) {
                var E = B * sh * media * C.r[k] * I.r * dep * lost * algo[k];
                eff.push(E);
                sales.push(A[k] * SAT[k] * (1 - Math.exp(-E / SAT[k])));
            });
            var sentMult = 0.4 + 0.6 * ((ds.brandSentiment || 70) / 70);
            var hit = (typeof ds.salesHit === 'number') ? ds.salesHit : 1;
            ds.salesHit = 1;
            var k2 = C.c * I.c * sentMult * hit * 1000000;
            var igRev = Math.round(sales[0] * k2), tkRev = Math.round(sales[1] * k2), liRev = Math.round(sales[2] * k2);
            var periodRevenue = igRev + tkRev + liRev;

            var igGrowth = Math.round(eff[0] * FPM[0]);
            var tkGrowth = Math.round(eff[1] * FPM[1]);
            var liGrowth = Math.round(eff[2] * FPM[2]);
            ds.igFollowers += igGrowth;
            ds.tkFollowers += tkGrowth;
            ds.liFollowers += liGrowth;
            ds.totalFollowers = ds.igFollowers + ds.tkFollowers + ds.liFollowers;

            var dS = C.s + (ds.crisisCarryOver || 0);
            ds.crisisCarryOver = 0;
            if (ds.exposure) { dS -= 3 * ds.exposure; ds.exposure = 0; }
            /* humour and trends on a TikTok-heavy mix reach minors and touch politics: it costs a quarter later */
            if (d.contentFocus === 'entertainment' && tk >= 0.4) ds.exposure = 1;

            var roundInfo = this.ROUNDS[t - 1];
            if (roundInfo.hasCrisis) {
                var sev = (t === 3 ? 1.2 : 1) *
                    (1 + ((ds.lastContent === 'entertainment' || d.contentFocus === 'entertainment') ? 0.25 : 0) +
                         (d.influencerType === 'macro' ? 0.25 : 0));
                var resp = d.crisisResponse;
                if (resp === 'pivot') { dS += -2 * sev; ds.crisisCarryOver = 4; }
                else if (resp === 'apologize') { dS += -4 * sev; ds.crisisCarryOver = -3; ds.reachLoss = 0.9; }
                else if (resp === 'ignore') { dS += -1 * sev; ds.crisisCarryOver = -9 * sev; ds.salesHit = 0.92; }
                else if (resp === 'defend') { dS += -10 * sev; ds.crisisCarryOver = -4 * sev; }
                ds.lastCrisisResponse = resp;
            }
            var before = ds.brandSentiment;
            ds.brandSentiment = Math.max(5, Math.min(100, Math.round(before + dS)));
            ds.lastContent = d.contentFocus;

            var eng = C.e * I.e * (1 - 0.25 * p) * (ds.brandSentiment / 70);
            ds.engagementRate = Math.round(Math.max(0.5, Math.min(12, eng)) * 100) / 100;

            ds.budget -= B * 1000000;
            ds.totalRevenue += periodRevenue;
            ds.revenueHistory.push(periodRevenue);
            ds.sentimentHistory.push(ds.brandSentiment);
            ds.followersHistory.push(ds.totalFollowers);
            ds.engagementHistory.push(ds.engagementRate);
            ds.organicReachPct = Math.round(R * 100);

            var sc = this._composite(ds, t);
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: sc.overall, salesScore: sc.sales, sentimentScore: sc.sentiment });
            ds.performanceTier = this._tierId(sc.overall);

            return {
                igGrowth: igGrowth, tkGrowth: tkGrowth, liGrowth: liGrowth,
                totalFollowers: ds.totalFollowers, engagementRate: ds.engagementRate,
                revenue: periodRevenue, igRevenue: igRev, tkRevenue: tkRev, liRevenue: liRev,
                sentiment: ds.brandSentiment, sentimentChange: ds.brandSentiment - before,
                organicReachPct: ds.organicReachPct, budget: ds.budget, overallScore: sc.overall
            };
        }

        /* One score for the gradebook, the verdict and the debrief: accumulated attributed sales
           (pace to year end, COP 350M to 950M) weighted 65, closing sentiment (35 to 85) weighted 35. */
        _composite(ds, periods) {
            var n = Math.max(1, periods || (ds.revenueHistory ? ds.revenueHistory.length : 1));
            var pace = (ds.totalRevenue || 0) / 1000000 * 4 / n;
            var s1 = Math.max(0, Math.min(1, (pace - 350) / (950 - 350)));
            var s2 = Math.max(0, Math.min(1, ((ds.brandSentiment || 0) - 35) / (85 - 35)));
            return {
                overall: Math.max(0, Math.min(100, Math.round(100 * (0.65 * s1 + 0.35 * s2)))),
                sales: Math.round(100 * s1),
                sentiment: Math.round(100 * s2)
            };
        }

        _tierId(score) {
            if (score >= 85) return 'strategist';
            if (score >= 70) return 'expert';
            if (score >= 50) return 'competent';
            return 'beginner';
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.budget',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('followersDisplay', 'domainState.totalFollowers',
                (v) => Math.round(v).toLocaleString());
            uiManager.bind('sentimentDisplay', 'domainState.brandSentiment',
                (v) => v + '%');
            uiManager.bind('revenueDisplay', 'domainState.totalRevenue',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('igFollowersDisplay', 'domainState.igFollowers',
                (v) => Math.round(v).toLocaleString());
            uiManager.bind('tkFollowersDisplay', 'domainState.tkFollowers',
                (v) => Math.round(v).toLocaleString());
            uiManager.bind('liFollowersDisplay', 'domainState.liFollowers',
                (v) => Math.round(v).toLocaleString());

            if (!this._wired) {
                var _self = this;
                var _refresh = function() {
                    try {
                        var _st = window.mySimulation.state;
                        _self._updateBriefing(_st);
                        var _dp = document.getElementById('debriefPanel');
                        if ((_st.history || []).length >= (_st.maxPeriods || 4)) {
                            _self._renderDebrief(_st);
                        } else if (_dp) {
                            _dp.style.display = 'none';
                        }
                    } catch (e) {}
                };
                var _sim = window.mySimulation;
                if (_sim && _sim.eventBus && typeof _sim.eventBus.on === 'function') {
                    _sim.eventBus.on('period:submitted', _refresh);
                    _sim.eventBus.on('period:undone', _refresh);
                }
                document.addEventListener('express:langchanged', _refresh);
                var _syncLi = function() {
                    var a = document.getElementById('instagramPctInput'), b = document.getElementById('tiktokPctInput'), c = document.getElementById('linkedinPctInput');
                    if (!a || !b || !c) return;
                    c.value = String(100 - (parseInt(a.value, 10) || 0) - (parseInt(b.value, 10) || 0));
                };
                ['instagramPctInput', 'tiktokPctInput'].forEach(function(id) {
                    var el = document.getElementById(id);
                    if (el) { el.addEventListener('input', _syncLi); el.addEventListener('change', _syncLi); }
                });
                _syncLi();
                this._wired = true;
            }
        }

