        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || null;
            return this._buildSummary(history, ds);
        }

        /* v1.2.0: verdict, sub-scores, turning point and insights all come from the run history and _composite */
        _buildSummary(history, ds) {
            var t = this._t.bind(this);
            var fmtN = function(v) { return Math.round(v).toLocaleString(); };
            var rows = history.map(function(h) { return { d: h.decisions || {}, r: h.results || {} }; });
            var totalRevenue = rows.reduce(function(s, x) { return s + (x.r.revenue || 0); }, 0);
            var last = rows[rows.length - 1].r;
            var finalSentiment = last.sentiment || 0;
            var finalFollowers = last.totalFollowers || 0;
            var sc = this._composite({ totalRevenue: totalRevenue, brandSentiment: finalSentiment, revenueHistory: rows }, rows.length);
            var tier = this._tierId(sc.overall);

            var count = function(fn) { return rows.filter(fn).length; };
            var quarters = function(fn) { var q = []; rows.forEach(function(x, i) { if (fn(x)) q.push('T' + (i + 1)); }); return q.join(', '); };
            var mistakes = [], good = [];

            /* M1 chasing virality */
            var viral = count(function(x) { return (x.d.tiktokPct || 0) >= 50 || x.d.contentFocus === 'entertainment'; });
            if (viral >= 2) {
                var tkGain = rows.reduce(function(s, x) { return s + (x.r.tkGrowth || 0); }, 0);
                var tkRev = rows.reduce(function(s, x) { return s + (x.r.tkRevenue || 0); }, 0);
                mistakes.push(this._fill(t('ins_viral'), { n: fmtN(tkGain), m: fmtN(tkRev / 1000000), q: quarters(function(x) { return (x.d.tiktokPct || 0) >= 50 || x.d.contentFocus === 'entertainment'; }) }));
            }
            /* M2 macro creators */
            var macro = count(function(x) { return x.d.influencerType === 'macro'; });
            if (macro >= 2) mistakes.push(this._fill(t('ins_macro'), { q: quarters(function(x) { return x.d.influencerType === 'macro'; }) }));
            /* M3 unpaid only */
            var avgPaid = rows.reduce(function(s, x) { return s + (x.d.paidPct || 0); }, 0) / rows.length;
            if (avgPaid < 20) mistakes.push(this._fill(t('ins_organic'), { p: Math.round(avgPaid), x: last.organicReachPct || 68 }));
            if (avgPaid > 85) mistakes.push(this._fill(t('ins_allpaid'), { p: Math.round(avgPaid) }));
            /* M4 to M5 and apology */
            var self = this;
            rows.forEach(function(x, i) {
                if (i !== 1 && i !== 2) return;
                var q = 'T' + (i + 1);
                if (x.d.crisisResponse === 'ignore') mistakes.push(self._fill(t('ins_silence'), { q: q }));
                else if (x.d.crisisResponse === 'defend') mistakes.push(self._fill(t('ins_defend'), { q: q }));
                else if (x.d.crisisResponse === 'apologize') mistakes.push(self._fill(t('ins_apology'), { q: q }));
            });
            /* other real errors of the situation */
            var salesQ = count(function(x) { return x.d.contentFocus === 'sales'; });
            if (salesQ >= 2) mistakes.push(this._fill(t('ins_salescontent'), { n: salesQ }));
            var conc = rows.filter(function(x) { return (x.d.instagramPct || 0) >= 70 || (x.d.linkedinPct || 0) >= 70; });
            if (conc.length >= 2) mistakes.push(t('ins_concentration'));

            /* what went right, only when it is true of this run */
            var spread = count(function(x) { return (x.d.instagramPct || 0) >= (x.d.tiktokPct || 0) && (x.d.instagramPct || 0) < 70 && (x.d.linkedinPct || 0) >= 5; });
            if (spread >= 3) good.push(t('ins_good_mix'));
            var micro = count(function(x) { return x.d.influencerType === 'micro'; });
            if (micro >= 3) good.push(t('ins_good_micro'));
            var piv = rows.filter(function(x, i) { return (i === 1 || i === 2) && x.d.crisisResponse === 'pivot'; }).length;
            if (piv === 2) good.push(t('ins_good_pivot'));
            if (avgPaid >= 35 && avgPaid <= 70) good.push(t('ins_good_paid'));

            /* turning point: the quarter where sentiment fell most, else the weakest sales quarter */
            var tp = null, worst = 0;
            rows.forEach(function(x, i) { if ((x.r.sentimentChange || 0) < worst) { worst = x.r.sentimentChange; tp = i; } });
            var turning;
            if (tp !== null && worst <= -5) {
                turning = this._fill(t('tp_sentiment'), { q: 'T' + (tp + 1), x: -worst, why: this._why(rows[tp].d, tp) });
            } else {
                turning = t('tp_none');
            }

            var insights = mistakes.concat(good).slice(0, 5);
            if (!insights.length) insights.push(t('insight_default'));

            return {
                totalRevenue: totalRevenue,
                avgRevenue: totalRevenue / rows.length,
                finalSentiment: finalSentiment,
                finalFollowers: finalFollowers,
                performance: tier,
                performanceKey: 'tier_' + tier,
                performanceLabel: t('tier_' + tier),
                overallScore: sc.overall,
                totalScore: sc.overall,
                score: sc.overall,
                composite: sc.overall,
                salesScore: sc.sales,
                sentimentScore: sc.sentiment,
                turningPoint: turning,
                insights: insights,
                questions: [t('dq_1'), t('dq_2'), t('dq_3')]
            };
        }

        _why(d, i) {
            var t = this._t.bind(this);
            if ((i === 1 || i === 2) && d.crisisResponse) return t('crisis_' + d.crisisResponse);
            return t('content_' + (d.contentFocus || 'mixed'));
        }

        _fill(s, vars) {
            return String(s).replace(/\{(\w+)\}/g, function(m, k) { return (vars && vars[k] !== undefined) ? vars[k] : m; });
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            if (!summary.performanceLabel) return '';
            var t = this._t.bind(this);
            var fmtN = function(v) { return Math.round(v || 0).toLocaleString(); };
            var li = function(arr) { return (arr || []).map(function(x) { return '<li>' + x + '</li>'; }).join(''); };
            return '<div class="social-sim-cm">' +
                '<p class="social-sim-cm-score"><strong>' + summary.overallScore + '/100</strong> · ' + summary.performanceLabel + '</p>' +
                '<p class="social-sim-cm-kpis">' + t('revenue_label') + ': $' + fmtN(summary.totalRevenue) +
                ' · ' + t('sentiment_label') + ': ' + summary.finalSentiment + '%' +
                ' · ' + t('followers_label') + ': ' + fmtN(summary.finalFollowers) + '</p>' +
                '<p class="social-sim-cm-sub">' + t('sub_sales') + ': ' + summary.salesScore + '/100 · ' + t('sub_sentiment') + ': ' + summary.sentimentScore + '/100</p>' +
                '<h4>' + t('tp_heading') + '</h4><p>' + summary.turningPoint + '</p>' +
                '<h4>' + t('insights_heading') + '</h4><ul>' + li(summary.insights) + '</ul>' +
                '<h4>' + t('dq_heading') + '</h4><ul>' + li(summary.questions) + '</ul>' +
                '</div>';
        }

        getHint(state, results) {
