            if ((results.sentimentChange || 0) <= -5) return this._fill(t('hint_sent_drop'), { x: -results.sentimentChange });
            if ((results.period || 1) >= 2 && results.organicReachPct) return this._fill(t('hint_reach'), { x: results.organicReachPct });
            return this._fill(t('hint_split'), {
                a: Math.round((results.igRevenue || 0) / 1000000), b: Math.round((results.tkRevenue || 0) / 1000000), c: Math.round((results.liRevenue || 0) / 1000000)
            });
        }

